INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2b-vignettes', 'Two ways of noticing', '{"slug": "sf2b-vignettes", "name": "Two ways of noticing", "questionnaire_type": "composable", "instructions": "People notice things in different ways. Our brains can toggle between two modes: a doing mode, which is goal-directed and uses knowledge we already have, and a sensing mode, which explores our sensory world to discover new things.\n\nIn the doing mode, we look or listen to accomplish something, like finding our keys, or checking out a body ache or a strange sound outside.\n\nIn the sensing mode, we look, listen, smell, taste or feel just out of curiosity, taking in whatever is there. Everyone does both at times, and neither is better. There are no right or wrong answers.", "pages": [{"id": "vig_p1", "components": [{"id": "vig_stem_1", "type": "information", "title": "How much is this person in the doing or sensing mode?", "body": "Rate each one from 1 Doing mode to 6 Sensing mode.", "image_url": "", "image_alt": ""}, {"id": "vig_1", "type": "likert", "question": "Priya walks along the shelves in the drug store, reading labels until finding the brand on her list.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}, {"id": "vig_2", "type": "likert", "question": "Walking home late, Riley listens for footsteps to make sure no one is following her.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}, {"id": "vig_3", "type": "likert", "question": "Waiting for a bus, Sam watches the light move on the wet road and listens to the cars go by.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}]}, {"id": "vig_p2", "components": [{"id": "vig_stem_2", "type": "information", "title": "How much is this person in the doing or sensing mode?", "body": "Rate each one from 1 Doing mode to 6 Sensing mode.", "image_url": "", "image_alt": ""}, {"id": "vig_4", "type": "likert", "question": "Lee is photographing the light on a building, then stops trying for the perfect shot and just takes in the view.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}, {"id": "vig_5", "type": "likert", "question": "In line at the ATM, Alex barely sees the street, busy working out a budget for next summer’s holiday.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}, {"id": "vig_6", "type": "likert", "question": "Walking down the hallway, Maya notices how each breath feels, then the warmth spreading through both hands.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}]}, {"id": "vig_p3", "components": [{"id": "vig_stem_3", "type": "information", "title": "How much is this person in the doing or sensing mode?", "body": "Rate each one from 1 Doing mode to 6 Sensing mode.", "image_url": "", "image_alt": ""}, {"id": "vig_7", "type": "likert", "question": "Jamie feels a racing heart and keeps checking it to make sure his heart rate goes back to normal.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}, {"id": "vig_8", "type": "likert", "question": "Drinking a morning coffee, Kai notices its bitterness and warmth, and that it tastes different from usual.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}, {"id": "vig_9", "type": "likert", "question": "In a noisy room, Noor strains to catch a phone number in a voicemail.", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}]}, {"id": "vig_p4", "components": [{"id": "vig_self_head", "type": "information", "title": "Now, about you", "body": "", "image_url": "", "image_alt": ""}, {"id": "vig_self", "type": "likert", "question": "The last time you had a few minutes with nothing to do, how much were you in the doing or sensing mode?", "scale": [{"value": 1, "label": "1 Doing mode"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6 Sensing mode"}], "required": true, "allow_pna": true}]}], "interleave": {"items": ["vig_1", "vig_2", "vig_3", "vig_4", "vig_5", "vig_6", "vig_7", "vig_8", "vig_9"], "page_sizes": [3, 3, 3], "groups": [{"items": ["vig_3", "vig_4", "vig_6", "vig_8"], "min_gap": 1, "max_per_page": 2, "min_per_page": 1}, {"items": ["vig_1", "vig_2", "vig_5", "vig_7", "vig_9"], "min_gap": 1, "max_per_page": 2, "min_per_page": 1}]}, "vignettes": [{"id": "vig_1", "source": "V1", "kind": "Doing: finding something", "sensing": false}, {"id": "vig_2", "source": "V2", "kind": "Doing: keeping watch", "sensing": false}, {"id": "vig_3", "source": "V3", "kind": "Sensing: around me", "sensing": true}, {"id": "vig_4", "source": "V4", "kind": "Sensing: letting go of a goal", "sensing": true}, {"id": "vig_5", "source": "V5", "kind": "Doing: planning", "sensing": false}, {"id": "vig_6", "source": "V6", "kind": "Sensing: in the body", "sensing": true}, {"id": "vig_7", "source": "V7", "kind": "Doing: checking the body", "sensing": false}, {"id": "vig_8", "source": "V8", "kind": "Sensing: taste", "sensing": true}, {"id": "vig_9", "source": "V9", "kind": "Doing: finding something", "sensing": false}], "scoring": {"note": "Not a scale. Separation = mean(sensing vignettes) - mean(doing vignettes), 1 = Doing mode, 6 = Sensing mode. vig_self is the self-rating on the same anchors."}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2b-scale', 'How you pay attention', '{"slug": "sf2b-scale", "name": "How you pay attention", "questionnaire_type": "composable", "instructions": "In general, how much do you agree with each statement? There are no right or wrong answers.", "pages": [{"id": "sf2b_p1", "components": [{"id": "sf2b_01", "type": "likert", "question": "As I go about my day, I notice the light, colours and sounds around me with interest", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2b_02", "type": "likert", "question": "Moving into the sensing mode is a struggle for me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2b_03", "type": "likert", "question": "I enjoy taking a moment just to notice how my body feels, like my breathing, the soles of my feet, or posture", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2b_04", "type": "likert", "question": "I enjoy exploring the sights, sounds and textures of ordinary moments", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2b_05", "type": "likert", "question": "When I walk somewhere familiar, I notice very little of what I pass", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2b_06", "type": "likert", "question": "Even in chores I have done many times, I notice sounds, smells or textures I had missed", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2b_07", "type": "likert", "question": "Even when I pause to take in what is around me, I react to stress the same way", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}, {"id": "sf2b_p2", "components": [{"id": "sf2b_08", "type": "likert", "question": "I can pay attention to what I’m feeling in my body in new or unfamiliar places", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2b_09", "type": "likert", "question": "It never seems to be the right time to go into the sensing mode", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2b_attn_agree", "type": "likert", "question": "To show that you are reading each statement, please select “Agree” for this one.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true}, {"id": "sf2b_10", "type": "likert", "question": "During my day, I take a moment to explore what I can see, hear and touch", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2b_11", "type": "likert", "question": "When I am busy, returning to the sensing mode feels like a low priority", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2b_12", "type": "likert", "question": "Looking closely at ordinary things around me often gives me a sense of wonder", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2b_13", "type": "likert", "question": "I react to things before I have really taken them in", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}], "items": [{"id": "sf2b_01", "source": "N4", "sf2a_id": "sf2a_40", "role": "8", "in_8": true, "in_10": true, "reverse_keyed": false}, {"id": "sf2b_02", "source": "sf6_36", "sf2a_id": "sf2a_02", "role": "8", "in_8": true, "in_10": true, "reverse_keyed": true, "study1_item": "sf6_36"}, {"id": "sf2b_03", "source": "V10", "sf2a_id": "sf2a_31", "role": "8", "in_8": true, "in_10": true, "reverse_keyed": false}, {"id": "sf2b_04", "source": "sf6_27", "sf2a_id": "sf2a_25", "role": "8", "in_8": true, "in_10": true, "reverse_keyed": false}, {"id": "sf2b_05", "source": "N6", "sf2a_id": "sf2a_42", "role": "exploratory", "in_8": false, "in_10": false, "reverse_keyed": true}, {"id": "sf2b_06", "source": "sfc_36", "sf2a_id": "sf2a_36", "role": "8", "in_8": true, "in_10": true, "reverse_keyed": false}, {"id": "sf2b_07", "source": "U4", "sf2a_id": "sf2a_19", "role": "8", "in_8": true, "in_10": true, "reverse_keyed": true}, {"id": "sf2b_08", "source": "A9", "sf2a_id": "sf2a_10", "role": "10", "in_8": false, "in_10": true, "reverse_keyed": false}, {"id": "sf2b_09", "source": "sfc_x2", "sf2a_id": "sf2a_37", "role": "8", "in_8": true, "in_10": true, "reverse_keyed": true}, {"id": "sf2b_10", "source": "sfc_35", "sf2a_id": "sf2a_39", "role": "8", "in_8": true, "in_10": true, "reverse_keyed": false}, {"id": "sf2b_11", "source": "sf6_44", "sf2a_id": "sf2a_27", "role": "exploratory", "in_8": false, "in_10": false, "reverse_keyed": true, "study1_item": "sf6_44"}, {"id": "sf2b_12", "source": "sfc_24", "sf2a_id": "sf2a_28", "role": "10", "in_8": false, "in_10": true, "reverse_keyed": false}, {"id": "sf2b_13", "source": "sfc_31", "sf2a_id": "sf2a_56", "role": "exploratory", "in_8": false, "in_10": false, "reverse_keyed": true}], "attention_checks": {"sf2b_attn_agree": 5}, "scoring": {"method": "mean", "reverse": "7 - x", "sf8": ["sf2b_01", "sf2b_02", "sf2b_03", "sf2b_04", "sf2b_06", "sf2b_07", "sf2b_09", "sf2b_10"], "sf10": ["sf2b_01", "sf2b_02", "sf2b_03", "sf2b_04", "sf2b_06", "sf2b_07", "sf2b_08", "sf2b_09", "sf2b_10", "sf2b_12"], "reverse_items": ["sf2b_02", "sf2b_05", "sf2b_07", "sf2b_09", "sf2b_11", "sf2b_13"], "unscored": ["sf2b_05", "sf2b_11", "sf2b_13"], "note": "The 8 is the primary score, the 10 secondary. \"Prefer not to answer\" is missing."}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2b-end', 'A few more statements', '{"slug": "sf2b-end", "name": "A few more statements", "questionnaire_type": "composable", "instructions": "A few more statements about how you pay attention. In general, how much do you agree with each statement? There are no right or wrong answers.", "pages": [{"id": "sf2b_end_p1", "components": [{"id": "sf6_9", "type": "likert", "question": "Moving into the sensing mode comes easily to me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf6_35", "type": "likert", "question": "I question my ability to move into the sensing mode", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf6_7", "type": "likert", "question": "Once I notice I have slipped into the doing mode without meaning to, I know how to shift back", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf6_8", "type": "likert", "question": "I can move into the sensing mode in new or unfamiliar places", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf2b_attn_disagree", "type": "likert", "question": "To show that you are reading each statement, please select “Disagree” for this one.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true}, {"id": "sf6_12", "type": "likert", "question": "Returning to the sensing mode feels worth prioritizing, even when I am busy", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf6_18", "type": "likert", "question": "When stress narrows my focus, returning to the sensing mode matters even more to me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf6_27", "type": "likert", "question": "I look forward to how sensory exploration feels, not just to getting better at it", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sf6_11", "type": "likert", "question": "I value time spent in the sensing mode, rather than always focusing on getting things done", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}], "attention_checks": {"sf2b_attn_disagree": 2}, "source": "PSY240 trial wording (psy240-sf-short-20, = Study 1 sf-pool6). With sf6_36 and sf6_44 in sf2b-scale (sf2b_02, sf2b_11) these complete the trial primary score, Access + Valuing and savouring."}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2b-maia2-brief', 'Body awareness', '{"slug": "sf2b-maia2-brief", "name": "Body awareness", "questionnaire_type": "composable", "instructions": "Below you will find a list of statements. Please indicate how often each statement applies to you generally in daily life (0 = Never, 5 = Always).", "pages": [{"id": "bmaia_p1", "components": [{"id": "maia_02", "type": "likert", "question": "I notice when I am uncomfortable in my body.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_03", "type": "likert", "question": "I notice where in my body I am comfortable.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_04", "type": "likert", "question": "I notice changes in my breathing, such as whether it slows down or speeds up.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_06", "type": "likert", "question": "I distract myself from sensations of discomfort.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_09", "type": "likert", "question": "I push feelings of discomfort away by focusing on something else.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_10", "type": "likert", "question": "When I feel unpleasant body sensations, I occupy myself with something else so I don’t have to feel them.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_11", "type": "likert", "question": "When I feel physical pain, I become upset.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_12", "type": "likert", "question": "I start to worry that something is wrong if I feel any discomfort.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}]}, {"id": "bmaia_p2", "components": [{"id": "maia_15", "type": "likert", "question": "When I am in discomfort or pain I can’t get it out of my mind.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_17", "type": "likert", "question": "I can maintain awareness of my inner bodily sensations even when there is a lot going on around me.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_19", "type": "likert", "question": "I can return awareness to my body if I am distracted.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_20", "type": "likert", "question": "I can refocus my attention from thinking to sensing my body.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_25", "type": "likert", "question": "I notice that my body feels different after a peaceful experience.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_26", "type": "likert", "question": "I notice that my breathing becomes free and easy when I feel comfortable.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_27", "type": "likert", "question": "I notice how my body changes when I feel happy / joyful.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_29", "type": "likert", "question": "When I bring awareness to my body I feel a sense of calm.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}]}, {"id": "bmaia_p3", "components": [{"id": "maia_30", "type": "likert", "question": "I can use my breath to reduce tension.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_31", "type": "likert", "question": "When I am caught up in thoughts, I can calm my mind by focusing on my body/breathing.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_32", "type": "likert", "question": "I listen for information from my body about my emotional state.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_33", "type": "likert", "question": "When I am upset, I take time to explore how my body feels.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_34", "type": "likert", "question": "I listen to my body to inform me about what to do.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_35", "type": "likert", "question": "I am at home in my body.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_36", "type": "likert", "question": "I feel my body is a safe place.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}, {"id": "maia_37", "type": "likert", "question": "I trust my body sensations.", "scale": [{"value": 0, "label": "0 Never"}, {"value": 1, "label": "1"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Always"}], "required": true, "allow_pna": true}]}], "scoring": {"method": "mean per subscale", "range": "0-5", "reverse": "5 - x", "reverse_items": ["maia_06", "maia_09", "maia_10", "maia_11", "maia_12", "maia_15"], "subscales": {"Noticing": ["maia_02", "maia_03", "maia_04"], "Not-Distracting": ["maia_06", "maia_09", "maia_10"], "Not-Worrying": ["maia_11", "maia_12", "maia_15"], "Attention Regulation": ["maia_17", "maia_19", "maia_20"], "Emotional Awareness": ["maia_25", "maia_26", "maia_27"], "Self-Regulation": ["maia_29", "maia_30", "maia_31"], "Body Listening": ["maia_32", "maia_33", "maia_34"], "Trusting": ["maia_35", "maia_36", "maia_37"]}, "source": "Brief MAIA-2: Rogowska, Tataruch & Klimowska (2023), Sci Rep 13:21270; items and wording from MAIA-2 (Mehling et al., 2018), keeping MAIA-2 item numbers."}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2b-bsss8', 'New experiences', '{"slug": "sf2b-bsss8", "name": "New experiences", "questionnaire_type": "composable", "instructions": "How much do you agree or disagree with each statement?", "pages": [{"id": "bsss_p1", "components": [{"id": "bsss_1", "type": "likert", "question": "I would like to explore strange places.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Neither agree nor disagree"}, {"value": 4, "label": "Agree"}, {"value": 5, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "bsss_2", "type": "likert", "question": "I get restless when I spend too much time at home.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Neither agree nor disagree"}, {"value": 4, "label": "Agree"}, {"value": 5, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "bsss_3", "type": "likert", "question": "I like to do frightening things.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Neither agree nor disagree"}, {"value": 4, "label": "Agree"}, {"value": 5, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "bsss_4", "type": "likert", "question": "I like wild parties.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Neither agree nor disagree"}, {"value": 4, "label": "Agree"}, {"value": 5, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "bsss_5", "type": "likert", "question": "I would like to take off on a trip with no pre-planned routes or timetables.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Neither agree nor disagree"}, {"value": 4, "label": "Agree"}, {"value": 5, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "bsss_6", "type": "likert", "question": "I prefer friends who are excitingly unpredictable.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Neither agree nor disagree"}, {"value": 4, "label": "Agree"}, {"value": 5, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "bsss_7", "type": "likert", "question": "I would like to try bungee jumping.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Neither agree nor disagree"}, {"value": 4, "label": "Agree"}, {"value": 5, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "bsss_8", "type": "likert", "question": "I would love to have new and exciting experiences, even if they are illegal.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Neither agree nor disagree"}, {"value": 4, "label": "Agree"}, {"value": 5, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}], "scoring": {"method": "mean", "range": "1-5", "reverse_items": [], "subscales": {"Experience seeking": ["bsss_1", "bsss_5"], "Boredom susceptibility": ["bsss_2", "bsss_6"], "Thrill and adventure seeking": ["bsss_3", "bsss_7"], "Disinhibition": ["bsss_4", "bsss_8"]}, "source": "Brief Sensation Seeking Scale (BSSS-8): Hoyle et al. (2002). Study 2b discriminant (decision 11)."}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2b-ncs6', 'Thinking', '{"slug": "sf2b-ncs6", "name": "Thinking", "questionnaire_type": "composable", "instructions": "For each statement, please indicate how characteristic it is of you.", "pages": [{"id": "ncs_p1", "components": [{"id": "ncs_01", "type": "likert", "question": "I would prefer complex to simple problems.", "scale": [{"value": 1, "label": "1 Extremely uncharacteristic of me"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Extremely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ncs_02", "type": "likert", "question": "I like to have the responsibility of handling a situation that requires a lot of thinking.", "scale": [{"value": 1, "label": "1 Extremely uncharacteristic of me"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Extremely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ncs_03", "type": "likert", "question": "Thinking is not my idea of fun.", "scale": [{"value": 1, "label": "1 Extremely uncharacteristic of me"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Extremely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ncs_04", "type": "likert", "question": "I would rather do something that requires little thought than something that is sure to challenge my thinking abilities.", "scale": [{"value": 1, "label": "1 Extremely uncharacteristic of me"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Extremely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ncs_11", "type": "likert", "question": "I really enjoy a task that involves coming up with new solutions to problems.", "scale": [{"value": 1, "label": "1 Extremely uncharacteristic of me"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Extremely characteristic of me"}], "required": true, "allow_pna": true}, {"id": "ncs_15", "type": "likert", "question": "I would prefer a task that is intellectual, difficult, and important to one that is somewhat important but does not require much thought.", "scale": [{"value": 1, "label": "1 Extremely uncharacteristic of me"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Extremely characteristic of me"}], "required": true, "allow_pna": true}]}], "scoring": {"method": "mean", "range": "1-5", "reverse": "6 - x", "reverse_items": ["ncs_03", "ncs_04"], "source": "Need for Cognition Scale-6: Lins de Holanda Coelho, Hanel & Wolf (2020); ids keep the NCS-18 item numbers. Study 2b discriminant (decision 18)."}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2b-spsq-sd', 'Light and sound', '{"slug": "sf2b-spsq-sd", "name": "Light and sound", "questionnaire_type": "composable", "instructions": "How much does each statement apply to you?", "pages": [{"id": "spsq_p1", "components": [{"id": "spsq_33", "type": "likert", "question": "I find harsh sounds very annoying.", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Moderately"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Extremely"}], "required": true, "allow_pna": true}, {"id": "spsq_07", "type": "likert", "question": "Brightly colored flickering lights are disturbing to me.", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Moderately"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Extremely"}], "required": true, "allow_pna": true}, {"id": "spsq_42", "type": "likert", "question": "I am often bothered by too bright light.", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Moderately"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Extremely"}], "required": true, "allow_pna": true}, {"id": "spsq_25", "type": "likert", "question": "I am easily disturbed by bright light or strong odors.", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4 Moderately"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 Extremely"}], "required": true, "allow_pna": true}]}], "scoring": {"method": "mean", "range": "1-7", "reverse_items": [], "source": "SPSQ-SF Sensory Discomfort subscale (4 items): De Gucht & Woestenburg (2025); English wording from the article''s supplement (developed in Dutch); 7-point scale as the SPSQ (1 not at all, 4 moderately, 7 extremely). Ids keep the SPSQ item numbers. Study 2b discriminant (decision 26)."}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2b-asi3-pc', 'Body sensations', '{"slug": "sf2b-asi3-pc", "name": "Body sensations", "questionnaire_type": "composable", "instructions": "How much do you agree with each statement as a general description of yourself? If a statement describes something you have never experienced, answer for how you think you would feel if you did.", "pages": [{"id": "asi_p1", "components": [{"id": "asi_03", "type": "likert", "question": "It scares me when my heart beats rapidly.", "scale": [{"value": 0, "label": "0 Very little"}, {"value": 1, "label": "1 A little"}, {"value": 2, "label": "2 Some"}, {"value": 3, "label": "3 Much"}, {"value": 4, "label": "4 Very much"}], "required": true, "allow_pna": true}, {"id": "asi_04", "type": "likert", "question": "When my stomach is upset, I worry that I might be seriously ill.", "scale": [{"value": 0, "label": "0 Very little"}, {"value": 1, "label": "1 A little"}, {"value": 2, "label": "2 Some"}, {"value": 3, "label": "3 Much"}, {"value": 4, "label": "4 Very much"}], "required": true, "allow_pna": true}, {"id": "asi_07", "type": "likert", "question": "When my chest feels tight, I get scared that I won''t be able to breathe properly.", "scale": [{"value": 0, "label": "0 Very little"}, {"value": 1, "label": "1 A little"}, {"value": 2, "label": "2 Some"}, {"value": 3, "label": "3 Much"}, {"value": 4, "label": "4 Very much"}], "required": true, "allow_pna": true}, {"id": "asi_08", "type": "likert", "question": "When I feel pain in my chest, I worry that I''m going to have a heart attack.", "scale": [{"value": 0, "label": "0 Very little"}, {"value": 1, "label": "1 A little"}, {"value": 2, "label": "2 Some"}, {"value": 3, "label": "3 Much"}, {"value": 4, "label": "4 Very much"}], "required": true, "allow_pna": true}, {"id": "asi_12", "type": "likert", "question": "When I notice my heart skipping a beat, I worry that there is something seriously wrong with me.", "scale": [{"value": 0, "label": "0 Very little"}, {"value": 1, "label": "1 A little"}, {"value": 2, "label": "2 Some"}, {"value": 3, "label": "3 Much"}, {"value": 4, "label": "4 Very much"}], "required": true, "allow_pna": true}, {"id": "asi_15", "type": "likert", "question": "When my throat feels tight, I worry that I could choke to death.", "scale": [{"value": 0, "label": "0 Very little"}, {"value": 1, "label": "1 A little"}, {"value": 2, "label": "2 Some"}, {"value": 3, "label": "3 Much"}, {"value": 4, "label": "4 Very much"}], "required": true, "allow_pna": true}]}], "scoring": {"method": "sum", "range": "0-24", "reverse_items": [], "source": "ASI-3 Physical Concerns subscale (items 3, 4, 7, 8, 12, 15): Taylor et al. (2007). Study 2b discriminant (decision 26)."}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2-samd-md', 'Meaning in events', '{"slug": "sf2-samd-md", "name": "Meaning in events", "questionnaire_type": "composable", "instructions": "Read carefully each of the following items and indicate the degree to which each of these items best describes you.", "pages": [{"id": "samd_p1", "components": [{"id": "samd_md_01", "type": "likert", "question": "I believe that unexplained events enable new discovery and development", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}, {"id": "samd_md_02", "type": "likert", "question": "I find signs of inner feelings in the external stimuli in the world around me", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}, {"id": "samd_md_03", "type": "likert", "question": "I find meaning in unexplained occurrences", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}, {"id": "samd_md_04", "type": "likert", "question": "I believe that listening to internal and external occurrences enables new discoveries", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}, {"id": "samd_md_05", "type": "likert", "question": "I sometimes feel that the environment “sends” me signals", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}, {"id": "samd_md_06", "type": "likert", "question": "Following experiences I’ve had, I have a sense of deep knowing of myself and the world", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}, {"id": "samd_md_07", "type": "likert", "question": "I am open to experiences that may not necessarily be explained by reason or causality", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}]}, {"id": "samd_p2", "components": [{"id": "samd_md_08", "type": "likert", "question": "I tend to be attentive to intuition in my everyday life", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}, {"id": "samd_md_09", "type": "likert", "question": "I am curious about surprising events in my life", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}, {"id": "samd_md_10", "type": "likert", "question": "I walk around in the world with a sense of awe and wonder from the opportunities and surprises that the world has to offer", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}, {"id": "samd_md_11", "type": "likert", "question": "It happens that things related to issues I am concerned with suddenly appear more in my everyday life", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}, {"id": "samd_md_12", "type": "likert", "question": "I believe that there is something to be learned from any event in life", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}, {"id": "samd_md_13", "type": "likert", "question": "I tend to be attentive to physical and bodily sensations (e.g., goosebumps, pain, sense of warmth)", "scale": [{"value": 1, "label": "1 Not at all"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5"}, {"value": 6, "label": "6"}, {"value": 7, "label": "7 To a high degree"}], "required": true, "allow_pna": true}]}], "scoring": {"method": "mean", "note": "Synchronicity Awareness and Meaning-Detecting Scale (SAMD), Meaning-Detecting subscale only (13 items, 1-7, no reverse-keyed items): Russo-Netzer & Icekson (2023), Frontiers in Psychology 13:1053296, Table 1, item wording and instructions as published (English back-translation of the Hebrew original). Article CC BY; authors to be told of the use. Study 2b: discriminant (decision 16).", "reverse_items": []}}'::jsonb)
INSERT INTO questionnaires (slug, name, definition) VALUES ('sf2b-pause', 'A short break', '{"slug": "sf2b-pause", "name": "A short break", "questionnaire_type": "composable", "instructions": "", "pages": [{"id": "pause_p1", "components": [{"id": "pause_1", "type": "sensing_pause", "slot": 1, "ask_context": true, "question": "Optional break"}]}], "scoring": {"note": "Behavioural criterion. Engaged pause = choice \"pause\", at least 20 s on the page, and time unfocused + hidden under half the total (decision 22). Where and how tired are asked after the decision."}}'::jsonb)
